import{z as n,x as B,o as e,c as p,q as A,j as s,D as E,d as l,s as r,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const V=JSON.parse('{"title":"放气","description":"","frontmatter":{"title":"放气","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/resist-outgassing.md","filePath":"litho/resist-outgassing.md","lastUpdated":1791063341000}'),d={name:"litho/resist-outgassing.md"};function D(h,a,m,c,f,u){const i=B("Mermaid");return e(),p("div",null,[a[2]||(a[2]=A('<h1 id="放气" tabindex="-1">放气 <a class="header-anchor" href="#放气" aria-label="Permalink to &quot;放气&quot;">​</a></h1><div class="epigraph"><p>真空里胶会吐分子；吐到多层膜上就是污染光学，灵敏度再好也过不了出气签核。</p><footer>—— 据 ASML 与抗蚀剂厂商对 EUV 胶放气 / 光学污染的公开讨论整理</footer></div><p><a href="/litho/euv-secondary-electron">上一课</a>把二次电子产额写成潜像核。缺口是同一套膜在真空扫描时还会挥发：碳氢与酸、配体碎片打到投影镜的 Mo/Si 多层膜上，反射率与 flare 一起坏。本课钉放气。随机缺孔留给<a href="/litho/stochastic-holes">下一课</a>，不在这里用平均 CD 代替缺陷尾。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>EUV 在真空中投影。CAR 的 PAG、淬灭剂、残留溶剂，锡氧胶的配体与小分子，底层的挥发分，都会在曝光与烘烤后继续出气。DUV 浸没有镜头最后表面与水的污染账；EUV 换成多层膜与膜（pellicle）的碳污染、氧化。ASML 公开把抗蚀剂出气资格当作上机条件：不是实验室对比度够就能进 NXE。</p><p>缺口不是再提高产额，而是卫生。把「更敏」写成无条件目标，会选出出气最凶的配方。把污染全部写成光源锡屑，会漏掉晶圆侧的碳氢。</p><h3 id="出气资格不是灵敏度曲线" tabindex="-1">出气资格不是灵敏度曲线 <a class="header-anchor" href="#出气资格不是灵敏度曲线" aria-label="Permalink to &quot;出气资格不是灵敏度曲线&quot;">​</a></h3><p>公开流程用见证片（witness sample）一类方法看膜层反射率损失或碳生长，再决定这支胶能不能进量产腔。数字与规程是厂商与用户合同，本课不编阈值、不编小时数。要记住的是：签核对象是光学寿命，不是 CD。</p><p><span class="marginnote">氢环境可以清一部分碳，却也带来膜与胶的其他化学。出气合格不等于「可以随便加剂量」。剂量高，曝光时间长，同一挥发速率下积分污染更大——与产能会计同一条时间轴。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>栈一起管：胶、底层、面涂（若有）、烘烤把溶剂赶掉的程度。底层课已经说过它可以当阻挡，也可以自己成为源。换胶族必须重做出气，不能假设锡氧比 CAR 更干净或更脏——配体挥发与有机 PAG 是不同物种。轨道上的后烘、延迟时间改变残留溶剂，出气指纹会变。</p><p>机台侧：气流、温度、氢清洗、pellicle 是否挡住一部分物种。这些是设备课，本课只要求胶的出气数据与机台资格匹配，而不是只报 RLS。</p><p><span class="marginnote">数字实例：总污染约等于挥发速率乘以曝光时间的积分。若把剂量从 30 mJ/cm² 降到 20 mJ/cm² 换「更敏」，单场曝光时间省三分之一，但新配方挥发速率若高三倍，落到镜片上的总量反而约翻倍——灵敏度的账面收益被出气账吃掉。</span></p><h3 id="与成像正交、与窗口相关" tabindex="-1">与成像正交、与窗口相关 <a class="header-anchor" href="#与成像正交、与窗口相关" aria-label="Permalink to &quot;与成像正交、与窗口相关&quot;">​</a></h3><p>出气不直接改 TCC。它改长期 flare 与反射率，从而慢慢改剂量到达和对比。短期则是资格门槛：过不了门，再好的 NILS 也印不成。CD 窗签核必须附带「这支胶已出气合格」，否则工艺窗是实验室窗。</p>',15)),(e(),s(o,null,{default:E(()=>[r(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20RES%5B%22%E8%83%B6%20%2F%20%E5%BA%95%E5%B1%82%E6%8C%A5%E5%8F%91%E5%88%86%22%5D%20--%3E%20VAC%5B%22EUV%20%E7%9C%9F%E7%A9%BA%22%5D%0A%20%20VAC%20--%3E%20ML%5B%22%E5%A4%9A%E5%B1%82%E8%86%9C%E7%A2%B3%E6%B1%A1%E6%9F%93%22%5D%0A%20%20ML%20--%3E%20R%5B%22%E5%8F%8D%E5%B0%84%E7%8E%87%20%2F%20flare%22%5D%0A%20%20QUAL%5B%22%E5%87%BA%E6%B0%94%E8%B5%84%E6%A0%BC%22%5D%20--%3E%20TOOL%5B%22%E8%83%BD%E5%90%A6%E4%B8%8A%E6%9C%BA%22%5D%0A%20%20SE%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E7%94%B5%E5%AD%90%E4%BA%A7%E9%A2%9D%22%5D%20--%3E%20LAT%5B%22%E6%BD%9C%E5%83%8F%22%5D%0A%20%20LAT%20--%3E%20QUAL%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[l("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"曝光打断键，小分子从自由体积里扩散到真空。EUV 每次吸收能量高，碎片通道比 DUV 光解更杂。物种落到多层膜上，改变周期膜的光学厚度与吸收，局部反射率下降，散射上升，像面台基（flare）抬高——暗区剂量上升，化学上又去打淬灭剂库存。于是卫生失败会回头变成成像失败，只是时间尺度是镜片寿命，不是单场。",-1)),(e(),s(o,null,{default:E(()=>[r(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20EUV%5B%22EUV%20%E5%85%89%E5%AD%90%E6%89%93%E6%96%AD%E9%94%AE%22%5D%20--%3E%20FRAG%5B%22%E5%B0%8F%E5%88%86%E5%AD%90%20%2F%20%E9%85%8D%E4%BD%93%E7%A2%8E%E7%89%87%22%5D%0A%20%20FRAG%20--%3E%20DIFF%5B%22%E5%9C%A8%E8%87%AA%E7%94%B1%E4%BD%93%E7%A7%AF%E4%B8%AD%E6%89%A9%E6%95%A3%22%5D%0A%20%20DIFF%20--%3E%20DESORB%5B%22%E8%84%B1%E9%99%84%E8%BF%9B%E5%85%A5%E7%9C%9F%E7%A9%BA%22%5D%0A%20%20DESORB%20--%3E%20DEP%5B%22%E8%90%BD%E5%88%B0%E5%A4%9A%E5%B1%82%E8%86%9C%E8%A1%A8%E9%9D%A2%22%5D%0A%20%20DEP%20--%3E%20LOSS%5B%22%E5%B1%80%E9%83%A8%E5%8F%8D%E5%B0%84%E7%8E%87%E4%B8%8B%E9%99%8D%22%5D%0A%20%20LOSS%20--%3E%20FLARE%5B%22flare%20%E6%8A%AC%E9%AB%98%20%2F%20%E6%9A%97%E5%8C%BA%E5%8F%98%E4%BA%AE%22%5D%0A%20%20FLARE%20--%3E%20DOSE%5B%22%E8%A2%AB%E8%BF%AB%E5%8A%A0%E5%A4%A7%E5%89%82%E9%87%8F%E8%A1%A5%E5%81%BF%22%5D%0A%20%20DOSE%20--%3E%20EUV%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p>锡氧胶的无机骨架本身不易挥发，配体和溶剂仍会。CAR 的酸与淬灭剂是已知的 DUV 污染源，在真空里同样在场。公开讨论把「低出气」写成与灵敏度并列的配方约束，而不是验收之后的环保附录。</p><p><span class="marginnote">直觉类比：出气像湿衣服在真空里「晾干」——不需要空气吹动，分子自己跑出来。骨架是衣服本体，配体与残留溶剂是没拧干的水；轨道上的烘烤就是提前把水拧掉，减少进真空后的持续挥发。</span></p><p><span class="marginnote">计量胶、BARC、底部抗反射在 DUV 轨道上的出气经验，不能直接当 EUV 多层膜合同。真空、氢、13.5 nm 光学是另一套材料兼容表。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写见证片的具体纳米碳厚规格，不编某型号镜片的寿命小时。不把光源 tin debris 与胶放气合成一个「污染」桶——锡屑是光源课，碳氢是本课。随机缺失下一课才成为良率墙；出气合格的胶仍可以因光子稀疏而缺孔。</p><p>DUV 193 nm 镜头出气/浸出已在面涂课；本课对象是 EUV 真空光学。不要把浸没 leaching 的水分析仪方法原样搬来当 EUV 资格。二次电子产额再高，也买不走出气门：上一课的灵敏度与本课的卫生是两条签核，缺一不可。</p><p><span class="marginnote">常见误区：看到反射率下降就归咎光源锡屑。锡屑是光源侧的金属颗粒物，胶放气主要是碳氢、酸与配体小分子——来源、成分、清洗手段都不同。混在一个「污染」桶里，会修错对象：该改胶配方却去清光源。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EUV 胶与底层的挥发分污染多层膜；出气资格是上机门槛。</li><li>更敏若换来更凶的出气，不是净收益；剂量积分放大污染。</li><li>底层可挡可源；换胶族必须重做资格。</li><li>污染抬 flare，长期会回头改成像，短期则是能不能进腔。</li><li>缺孔统计下一课；本课不代替随机尾。</li><li>灵敏度与出气资格是两条签核，缺一不可。</li><li>出处：ASML 对 EUV 抗蚀剂出气与光学污染的公开要求；胶栈公开讨论。</li></ul>',9))])}const F=n(d,[["render",D]]);export{V as __pageData,F as default};
